CREATE TABLE "roles" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL
);

CREATE TABLE "usuarios" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_usuario" varchar UNIQUE NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "password" varchar NOT NULL,
  "rol_id" int NOT NULL,
  "personal_id" int
);

CREATE TABLE "personal" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "apellido" varchar NOT NULL,
  "telefono" varchar,
  "email" varchar UNIQUE,
  "fecha_ingreso" date,
  "activo" boolean DEFAULT true
);

CREATE TABLE "especialidades" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL,
  "descripcion" text
);

CREATE TABLE "personal_especialidad" (
  "personal_id" int,
  "especialidad_id" int,
  PRIMARY KEY ("personal_id", "especialidad_id")
);

CREATE TABLE "turnos_personal" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "personal_id" int NOT NULL,
  "dia_semana" int NOT NULL,
  "hora_inicio" time NOT NULL,
  "hora_fin" time NOT NULL
);

CREATE TABLE "horarios_atencion" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dia_semana" int NOT NULL,
  "hora_apertura" time NOT NULL,
  "hora_cierre" time NOT NULL
);

CREATE TABLE "clientes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "apellido" varchar NOT NULL,
  "telefono" varchar,
  "email" varchar,
  "fecha_registro" date DEFAULT (now())
);

CREATE TABLE "preferencias_cliente" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cliente_id" int NOT NULL,
  "categoria" varchar,
  "descripcion" text NOT NULL
);

CREATE TABLE "categorias_servicio" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL,
  "descripcion" text
);

CREATE TABLE "servicios" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "categoria_id" int NOT NULL,
  "nombre" varchar NOT NULL,
  "descripcion" text,
  "duracion_minutos" int NOT NULL,
  "activo" boolean DEFAULT true
);

CREATE TABLE "precios_servicio" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "servicio_id" int NOT NULL,
  "precio" decimal NOT NULL,
  "vigente_desde" date NOT NULL,
  "vigente_hasta" date
);

CREATE TABLE "descuentos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "tipo" varchar NOT NULL,
  "valor" decimal NOT NULL,
  "fecha_inicio" date,
  "fecha_fin" date,
  "activo" boolean DEFAULT true
);

CREATE TABLE "metodos_pago" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar UNIQUE NOT NULL
);

CREATE TABLE "reservas" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cliente_id" int NOT NULL,
  "personal_id" int NOT NULL,
  "fecha" date NOT NULL,
  "hora_inicio" time NOT NULL,
  "hora_fin" time NOT NULL,
  "estado" varchar NOT NULL DEFAULT 'pendiente',
  "descuento_id" int,
  "a_domicilio" boolean NOT NULL DEFAULT false,
  "direccion_domicilio" varchar(255),
  "minutos_traslado" int NOT NULL DEFAULT 0,
  "created_at" timestamp DEFAULT (now()),
  CONSTRAINT "reservas_domicilio_con_direccion" CHECK ("a_domicilio" = false OR "direccion_domicilio" IS NOT NULL),
  CONSTRAINT "reservas_traslado_solo_domicilio" CHECK ("minutos_traslado" BETWEEN 0 AND 240 AND ("a_domicilio" = true OR "minutos_traslado" = 0))
);

CREATE TABLE "detalle_reserva" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reserva_id" int NOT NULL,
  "servicio_id" int NOT NULL,
  "precio_aplicado" decimal NOT NULL,
  "cantidad" int NOT NULL DEFAULT 1,
  "agregado_en_el_momento" boolean NOT NULL DEFAULT false
);

CREATE TABLE "historial_visitas" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reserva_id" int UNIQUE NOT NULL,
  "notas" text,
  "fecha_realizada" date NOT NULL
);

CREATE TABLE "pagos_ingresos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reserva_id" int,
  "metodo_pago_id" int NOT NULL,
  "monto" decimal NOT NULL,
  "fecha" timestamp DEFAULT (now()),
  "descripcion" varchar
);

CREATE TABLE "stock_recursos" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "descripcion" text,
  "unidad_medida" varchar,
  "cantidad_actual" decimal NOT NULL DEFAULT 0,
  "stock_minimo" decimal DEFAULT 0
);

CREATE TABLE "movimientos_stock" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "recurso_id" int NOT NULL,
  "tipo" varchar NOT NULL,
  "cantidad" decimal NOT NULL,
  "fecha" timestamp DEFAULT (now()),
  "motivo" varchar
);

CREATE TABLE "servicio_recurso" (
  "servicio_id" int,
  "recurso_id" int,
  "cantidad_utilizada" decimal NOT NULL,
  PRIMARY KEY ("servicio_id", "recurso_id")
);

CREATE TABLE "detalle_reserva_recurso" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "detalle_reserva_id" int NOT NULL,
  "recurso_id" int NOT NULL,
  "cantidad_utilizada" decimal NOT NULL
);

CREATE INDEX "reservas_personal_fecha_index" ON "reservas" ("personal_id", "fecha");

CREATE INDEX "reservas_fecha_index" ON "reservas" ("fecha");

CREATE INDEX "detalle_reserva_reserva_index" ON "detalle_reserva" ("reserva_id");

CREATE INDEX "pagos_ingresos_reserva_index" ON "pagos_ingresos" ("reserva_id");

CREATE INDEX "pagos_ingresos_fecha_index" ON "pagos_ingresos" ("fecha");

CREATE INDEX "movimientos_stock_recurso_id_fecha_index" ON "movimientos_stock" ("recurso_id", "fecha");

CREATE INDEX "horarios_atencion_dia_semana_index" ON "horarios_atencion" ("dia_semana");

CREATE UNIQUE INDEX "detalle_reserva_recurso_detalle_reserva_id_recurso_id_unique" ON "detalle_reserva_recurso" ("detalle_reserva_id", "recurso_id");

COMMENT ON COLUMN "reservas"."estado" IS 'pendiente | confirmada | cancelada | completada | no_asistio';

COMMENT ON COLUMN "reservas"."a_domicilio" IS 'true si la cita se atiende fuera del salón';

COMMENT ON COLUMN "reservas"."direccion_domicilio" IS 'Dirección con referencias; obligatoria cuando a_domicilio = true';

COMMENT ON COLUMN "reservas"."minutos_traslado" IS 'Minutos de traslado (0 a 240) que ocupan al profesional antes y después de una cita a domicilio; 0 en el salón';

COMMENT ON COLUMN "personal"."email" IS 'Único sin distinguir mayúsculas (se guarda en minúsculas)';

ALTER TABLE "detalle_reserva_recurso" ADD FOREIGN KEY ("detalle_reserva_id") REFERENCES "detalle_reserva" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "detalle_reserva_recurso" ADD FOREIGN KEY ("recurso_id") REFERENCES "stock_recursos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuarios" ADD FOREIGN KEY ("rol_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuarios" ADD FOREIGN KEY ("personal_id") REFERENCES "personal" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "personal_especialidad" ADD FOREIGN KEY ("personal_id") REFERENCES "personal" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "personal_especialidad" ADD FOREIGN KEY ("especialidad_id") REFERENCES "especialidades" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "turnos_personal" ADD FOREIGN KEY ("personal_id") REFERENCES "personal" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "preferencias_cliente" ADD FOREIGN KEY ("cliente_id") REFERENCES "clientes" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "servicios" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias_servicio" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "precios_servicio" ADD FOREIGN KEY ("servicio_id") REFERENCES "servicios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservas" ADD FOREIGN KEY ("cliente_id") REFERENCES "clientes" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservas" ADD FOREIGN KEY ("personal_id") REFERENCES "personal" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservas" ADD FOREIGN KEY ("descuento_id") REFERENCES "descuentos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "detalle_reserva" ADD FOREIGN KEY ("reserva_id") REFERENCES "reservas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "detalle_reserva" ADD FOREIGN KEY ("servicio_id") REFERENCES "servicios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "historial_visitas" ADD FOREIGN KEY ("reserva_id") REFERENCES "reservas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pagos_ingresos" ADD FOREIGN KEY ("reserva_id") REFERENCES "reservas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pagos_ingresos" ADD FOREIGN KEY ("metodo_pago_id") REFERENCES "metodos_pago" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "movimientos_stock" ADD FOREIGN KEY ("recurso_id") REFERENCES "stock_recursos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "servicio_recurso" ADD FOREIGN KEY ("servicio_id") REFERENCES "servicios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "servicio_recurso" ADD FOREIGN KEY ("recurso_id") REFERENCES "stock_recursos" ("id") DEFERRABLE INITIALLY IMMEDIATE;
